{
  "title": "迷雾之森",
  "scene": "你站在一片古老森林的入口，周围弥漫着淡淡的雾气。据部落长老所述，这片森林深处藏有一件上古神器，但前往的路上充满了危险。森林入口的左侧有一座小石碑，上面刻着模糊的文字。右侧的树丛中，隐约可见一只异兽的眼睛在闪动。前方是一条看似平缓的小径，通向森林深处。",
  "goal": "找到前往上古神器的正确路径",
  "clue": "小石碑上的文字（玩家可见）",
  "choices": [
    {
      "id": "A",
      "text": "沿着小径前进",
      "outcome": "你沿着小径走了不久，发现前方的路被倒下的树木阻挡，但你能绕过去继续前进。显然这里不是最佳路线，但你没有遇到险情。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "观察异兽",
      "outcome": "你小心翼翼地靠近树丛，发现那是一只温顺的山海异兽，它用眼神指引你绕过森林的危险，带你找到了一条更安全的路径。这是个友好的信号，暗示这里并不是真正的威胁。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "解读石碑",
      "outcome": "你走近石碑，虽然文字模糊，但依稀可以辨认出几行提到了‘右侧非敌，左侧有阻’。按照这些提示，你找到了正确的路径，顺利进入森林深处。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
